_CORE_SRC = '# Action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Cost: cost_p = 3.0 * (trucks of p not on p\'s base)\n#              + 1.5 * (scooters of p not on p\'s base).\n# Moves precede service; stock regenerates after service and is rounded to 2 decimals.\n\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 60\nUNIT_TYPES = {\n    "truck": (8, 3.0, 1),\n    "scooter": (3, 1.5, 2),\n}\n\n\ndef payout(own_capacity, opponent_capacity, stock):\n    denominator = max(own_capacity + opponent_capacity, stock)\n    if denominator <= 0:\n        return 0.0\n    return own_capacity * stock / denominator\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n    distances = []\n    for source in range(n):\n        d = [n + 1] * n\n        d[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if d[v] == n + 1:\n                    d[v] = d[u] + 1\n                    queue.append(v)\n        distances.append(d)\n    return distances\n\n\ndef route_to_target(source, target, speed, horizon, distances):\n    route = []\n    position = source\n    for _ in range(horizon):\n        if distances[position][target] <= speed:\n            position = target\n        else:\n            choices = [\n                v for v in range(len(distances))\n                if distances[position][v] <= speed\n                and distances[v][target] == distances[position][target] - speed\n            ]\n            if choices:\n                position = min(choices)\n        route.append(position)\n    return route\n\n\ndef legal_action(units, destinations, distances):\n    moves = {}\n    n = len(distances)\n    for uid in sorted(destinations):\n        if uid not in units:\n            continue\n        kind, source = units[uid]\n        if kind not in UNIT_TYPES:\n            continue\n        destination = int(destinations[uid])\n        if (0 <= destination < n\n                and distances[source][destination] <= UNIT_TYPES[kind][2]\n                and destination != source):\n            moves[str(uid)] = int(destination)\n    return {"moves": moves}\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.distances = None\n        self.targets = {}\n        self.bad_reports = 0\n\n    def act(self, obs):\n        started = time.perf_counter()\n        deadline = started + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        units = obs.get("player_units", {})\n        if not n or not units:\n            return {"moves": {}}\n\n        edges = obs.get("edges", [])\n        key = (n, tuple(tuple(edge) for edge in edges))\n        if self.map_key != key:\n            self.distances = preprocess_map(n, edges)\n            self.map_key = key\n            self.targets = {}\n        distances = self.distances\n        home = int(obs["player_base"])\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n\n        remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n        if remaining == 0:\n            return {"moves": {}}\n        horizon = min(6, remaining)\n        stock = list(obs["stock"])\n        maxima = list(obs["stock_max"])\n        regen = list(obs["regen"])\n\n        enemy = [0] * n\n        for kind, position in obs.get("opponent_units", {}).values():\n            if kind in UNIT_TYPES and 0 <= position < n:\n                enemy[position] += UNIT_TYPES[kind][0]\n\n        # All plans start by recalling unused couriers. Candidate routes include\n        # service on intermediate nodes, not merely service after arrival.\n        ids = sorted(units, key=lambda u: (\n            0 if units[u][0] == "truck" else 1, u))\n        routes = {}\n        capacities = [[0] * n for _ in range(horizon)]\n        costs = [0.0] * horizon\n        chosen = {}\n        terminal = {}\n        options = {}\n\n        for uid in ids:\n            kind, source = units[uid]\n            cap, cost, speed = UNIT_TYPES[kind]\n            candidates = [home] + [\n                v for v in range(n) if v != home and maxima[v] > 0\n            ]\n            options[uid] = {\n                v: route_to_target(source, v, speed, horizon, distances)\n                for v in candidates\n            }\n            path = options[uid][home]\n            routes[uid] = path\n            chosen[uid] = home\n            for t, v in enumerate(path):\n                capacities[t][v] += cap\n                if v != home:\n                    costs[t] += cost\n            terminal[uid] = 0.0\n\n        # Forecast stocks using the exact depletion law and visible, stationary\n        # opponent capacities. The objective is profit difference, so denial counts.\n        def evaluate():\n            stocks = stock[:]\n            value = 0.0\n            for t in range(horizon):\n                value -= costs[t]\n                caps = capacities[t]\n                for v in range(n):\n                    a = caps[v]\n                    b = enemy[v]\n                    s = stocks[v]\n                    ours = payout(a, b, s)\n                    theirs = payout(b, a, s)\n                    value += ours - theirs\n                    stocks[v] = round(min(\n                        maxima[v], s - ours - theirs + regen[v]), 2)\n            return value - sum(terminal.values())\n\n        def replace(uid, path):\n            kind = units[uid][0]\n            cap, cost, speed = UNIT_TYPES[kind]\n            old = routes[uid]\n            for t in range(horizon):\n                a, b = old[t], path[t]\n                if a != b:\n                    capacities[t][a] -= cap\n                    capacities[t][b] += cap\n                    costs[t] += cost * (int(b != home) - int(a != home))\n            routes[uid] = path\n            # Approximate the eventual cost of recalling a courier beyond the\n            # forecast. No liability exists beyond the actual last game turn.\n            if remaining > horizon:\n                steps = (distances[path[-1]][home] + speed - 1) // speed\n                terminal[uid] = 0.65 * cost * max(0, steps - 1)\n            else:\n                terminal[uid] = 0.0\n\n        # Coordinate marginal allocation: each unit is removed before its best\n        # addition is chosen, so already allocated capacity and depletion count.\n        # The second pass frees allocations made obsolete by later couriers.\n        passes = 1 if self.bad_reports >= 2 else 2\n        for iteration in range(passes):\n            for uid in ids:\n                if time.perf_counter() >= deadline:\n                    break\n                current = chosen[uid]\n                best_target = current\n                best_value = evaluate()\n                prior = self.targets.get(uid)\n                for target in options[uid]:\n                    if time.perf_counter() >= deadline:\n                        break\n                    replace(uid, options[uid][target])\n                    value = evaluate()\n                    # A small switching premium preserves stable destinations,\n                    # while still abandoning depleted nodes promptly.\n                    premium = 0.30 if target == prior else 0.0\n                    best_premium = 0.30 if best_target == prior else 0.0\n                    if value + premium > best_value + best_premium + 1e-8:\n                        best_value = value\n                        best_target = target\n                replace(uid, options[uid][best_target])\n                chosen[uid] = best_target\n            if time.perf_counter() >= deadline:\n                break\n\n        self.targets = dict(chosen)\n        destinations = {uid: routes[uid][0] for uid in ids}\n        return legal_action(units, destinations, distances)\n'
_CORE_CLASS = 'Strategy'
